class Jornal {
    titulos : string[]
    materias : string[]

    constructor(titulos : string[], materias : string[]) {
        this.titulos = null
        this.materias = null
    }
}

function quantidadeNoticias(jornal : string, palavra : Jornal) : number {
    let quantidade : number = 0

    for (let i : number = 0; i < jornal.materias[i].length; i++) {
        // indexOf retorna o índice da palavra em um array
        if (jornal.materias[i].indexOf(palavra) != -1) {
            quantidade++
        }
    }
    return quantidade
}

class T {
    c : string = ""
    f : string = ""
    r : string = ""
}

function op(s : T) {
    let k : string = s.c + s.f + s.r

    s.c = s.f = s.r = ""

    for (let i : number = 0; i < k.length; i = i + 3) {
        s.c = s.c + k[i]
        s.f = s.f + k[i + 1]
        s.r = s.r + k[i + 2]
    }
}

let ws : T = { c : "YTU", f : "OHL", r : "UF."}

op(ws)

